INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Proxy immer für Sicherheitszwecke notwendig?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Caching oder Lastverteilung genutzt"}, {"text": "Ja", "correct": false, "because": "Mehrere Funktionen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel eines Proxys?', 3, '[{"text": "Datenverkehr vermitteln", "correct": true, "because": "Zwischen Client und Server"}, {"text": "Daten speichern", "correct": false, "because": "Nicht primäre Funktion"}, {"text": "Manuelle Steuerung", "correct": false, "because": "Automatisiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arten von Proxys gibt es?', 5, '[{"text": "Forward Proxy", "correct": true, "because": "Vermittelt für Clients"}, {"text": "Reverse Proxy", "correct": true, "because": "Schützt Server"}, {"text": "Cloud Proxy", "correct": false, "because": "Kein Standardbegriff"}, {"text": "Musik Proxy", "correct": false, "because": "Nicht definiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Proxy kann anonymisieren. b) Er ersetzt eine Firewall.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ergänzt, nicht ersetzt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Konfiguration eines Proxys?', 4, '[{"text": "Sicherheitsrichtlinien", "correct": false, "because": "Schützen Netzwerk"}, {"text": "Cache-Einstellungen", "correct": false, "because": "Beeinflussen Leistung"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant für Proxy"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Proxy den Datenverkehr verschlüsselt?', 2, '[{"text": "Nein", "correct": true, "because": "Nur bei speziellen Proxys wie HTTPS"}, {"text": "Ja", "correct": false, "because": "Nicht standardmäßig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion hat ein Reverse Proxy?', 3, '[{"text": "Server schützen", "correct": true, "because": "Verteilt Anfragen, verbirgt Server"}, {"text": "Client anonymisieren", "correct": false, "because": "Aufgabe eines Forward Proxy"}, {"text": "Manuelle Weiterleitung", "correct": false, "because": "Automatisiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Proxy?', 5, '[{"text": "Sicherheit", "correct": true, "because": "Verbirgt interne Strukturen"}, {"text": "Leistungssteigerung", "correct": true, "because": "Durch Caching"}, {"text": "Direkte Datenbearbeitung", "correct": false, "because": "Nicht primär"}, {"text": "Grafische Darstellung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein Proxy kann Inhalte filtern. b) Er ist immer transparent. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) kann anonym oder transparent sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen Proxy?', 4, '[{"text": "Netzwerkkonfiguration", "correct": false, "because": "Sichert Funktion"}, {"text": "Zugriffsregeln", "correct": false, "because": "Steuern Verkehr"}, {"text": "Musikwiedergabe", "correct": true, "because": "Irrelevant für Proxy"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Proxy dasselbe wie eine Firewall?', 2, '[{"text": "Nein", "correct": true, "because": "Proxy vermittelt, Firewall schützt"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Funktionen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei Proxys auftreten?', 4, '[{"text": "Leistungsverlust", "correct": true, "because": "Zusätzliche Verarbeitung"}, {"text": "Konfigurationsfehler", "correct": true, "because": "Beeinträchtigen Funktion"}, {"text": "Bildschirmauflösung", "correct": false, "because": "Kein Proxy-Problem"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Proxys immer anonym sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Können anonym oder transparent sein"}, {"text": "Ja", "correct": false, "because": "Nicht immer anonym"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Proxy-Konfiguration?', 3, '[{"text": "Sicherheitsrichtlinien", "correct": true, "because": "Schützen Netzwerk"}, {"text": "Maximale Verbindungen", "correct": false, "because": "Leistung wichtiger"}, {"text": "Manuelle Steuerung", "correct": false, "because": "Automatisierung besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Proxy kann Last verteilen. b) Er ersetzt einen VPN-Server.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) hat andere Funktion"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tools unterstützen Proxys?', 5, '[{"text": "Squid", "correct": true, "because": "Populärer Proxy-Server"}, {"text": "NGINX", "correct": true, "because": "Als Reverse Proxy nutzbar"}, {"text": "Texteditor", "correct": false, "because": "Kein Proxy-Tool"}, {"text": "Musiksoftware", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Proxy unwichtig?', 3, '[{"text": "Sicherheitskonfiguration", "correct": false, "because": "Schützt Netzwerk"}, {"text": "Leistung", "correct": false, "because": "Beeinflusst Verkehr"}, {"text": "Grafikdesign", "correct": true, "because": "Kein Proxy-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Proxy Inhalte filtern kann?', 2, '[{"text": "Ja", "correct": true, "because": "Z. B. für Zugriffsbeschränkungen"}, {"text": "Nein", "correct": false, "because": "Filterfunktion üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Arbeitet ein Proxy auf der Anwendungsschicht?', 3, '[{"text": "Ja", "correct": true, "because": "OSI-Schicht 7"}, {"text": "Nein", "correct": false, "because": "Anwendungsschicht typisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einem Proxy?', 4, '[{"text": "Firmennetzwerk mit Web-Filter", "correct": true, "because": "Proxy steuert Zugriff"}, {"text": "Musikwiedergabe", "correct": false, "because": "Kein Netzwerkbezug"}, {"text": "Bildbearbeitung", "correct": false, "because": "Nicht netzwerkrelevant"}]');
